      "value": "try:
    import json
    import re
    import datetime
    vars['decision_route'] = 'identity'
    vars['identity_say'] = 'I do not have that information available. You can contact Freya Bank through the mobile app or a branch.'
    vars['collection_say'] = 'I do not have that information available.'
    vars['id_stage'] = 'technical'
    for key, value in dict(close_attempted='no', close_state='idle', farewell_done='no', finalization_committed='no', action_payload=dict(), action_index=-1, transfer_requested='', callback_authorized='no').items():
        vars.setdefault(key, value)
    now = datetime.datetime.fromisoformat(str(vars.get('now', '')))
    today = now.date()
    holidays = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    months = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
    def unpack(value, fallback):
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except Exception:
                return fallback
        return value if isinstance(value, type(fallback)) else fallback
    def business(day):
        return day.weekday() < 5 and day.isoformat() not in holidays
    def following(day):
        while not business(day):
            day += datetime.timedelta(days=1)
        return day
    def advance(count):
        day = today
        for unused in range(count):
            day = following(day + datetime.timedelta(days=1))
        return day
    monday = today - datetime.timedelta(days=today.weekday())
    offer_day = monday + datetime.timedelta(days=6)
    while not business(offer_day):
        offer_day -= datetime.timedelta(days=1)
    if offer_day == today:
        offer_day = monday + datetime.timedelta(days=13)
        while not business(offer_day):
            offer_day -= datetime.timedelta(days=1)
    vars['attempt_one_date'] = offer_day.isoformat() if offer_day >= today else ''
    vars['attempt_one_policy_gap'] = 'yes' if offer_day < today else 'no'
    def spoken_date(value):
        day = datetime.date.fromisoformat(str(value))
        return str(day.day) + ' ' + months[day.month - 1].title() + ' ' + str(day.year)
    def money(value):
        value = float(value)
        return format(int(value), ',') if value.is_integer() else str(value)
    def parse_date(text, context):
        s = str(text).lower().strip().replace(',', '')
        s = re.sub(r'(?<=[a-z])-(?=[a-z])', ' ', s)
        ctx = dict(context)
        values = dict(first=1, second=2, third=3, fourth=4, fifth=5, sixth=6, seventh=7, eighth=8, ninth=9, tenth=10, eleventh=11, twelfth=12, thirteenth=13, fourteenth=14, fifteenth=15, sixteenth=16, seventeenth=17, eighteenth=18, nineteenth=19, twentieth=20, thirtieth=30, one=1, two=2, three=3, four=4, five=5, six=6, seven=7, eight=8, nine=9, ten=10, eleven=11, twelve=12, thirteen=13, fourteen=14, fifteen=15, sixteen=16, seventeen=17, eighteen=18, nineteen=19)
        def number(match):
            words = match.group(0).split()
            if words[0] in ['twenty', 'thirty']:
                return str((20 if words[0] == 'twenty' else 30) + (values.get(words[1], 0) if len(words) > 1 else 0))
            return str(values[words[0]])
        pattern = r'\b(?:twenty|thirty)(?:\s+(?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|one|two|three|four|five|six|seven|eight|nine))?\b|\b(?:' + '|'.join(sorted(values, key=len, reverse=True)) + r')\b'
        s = re.sub(pattern, number, s)
        s = re.sub(r'(\d)(st|nd|rd|th)\b', r'\1', s)
        s = re.sub(r'\s+', ' ', s).strip()
        if s in ['today', 'tomorrow', 'day after tomorrow', 'the day after tomorrow']:
            return today + datetime.timedelta(days=0 if s == 'today' else 1 if s == 'tomorrow' else 2), ctx, 'exact'
        match = re.fullmatch(r'in (\d+) days?', s)
        if match:
            return today + datetime.timedelta(days=int(match.group(1))), ctx, 'exact'
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            return datetime.date.fromisoformat(s), ctx, 'exact'
        if re.search(r'\b(next|coming|following)( calendar)? week\b|\bweek after this\b', s):
            start = monday + datetime.timedelta(days=7)
            ctx = dict(start=start.isoformat(), end=(start + datetime.timedelta(days=6)).isoformat(), year=start.year, month=start.month)
            s = re.sub(r'\b(next|coming|following)( calendar)? week\b|\bweek after this\b', '', s).strip()
        elif re.search(r'\bthis( calendar)? week\b', s):
            ctx = dict(start=monday.isoformat(), end=(monday + datetime.timedelta(days=6)).isoformat(), year=monday.year, month=monday.month)
            s = re.sub(r'\bthis( calendar)? week\b', '', s).strip()
        if re.search(r'\b(next|coming|following) month\b', s):
            day = (today.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            ctx = dict(year=day.year, month=day.month)
            s = re.sub(r'\b(next|coming|following) month\b', '', s).strip()
        elif re.search(r'\bthis month\b|\bend of (the )?month\b|\bmonth end\b', s):
            ctx = dict(year=today.year, month=today.month)
        named_month = next((index + 1 for index, name in enumerate(months) if re.search(r'\b' + name + r'\b', s)), 0)
        explicit_year = re.search(r'\b(?:19|20|21)\d{2}\b', s)
        if named_month:
            ctx = dict(year=int(explicit_year.group(0)) if explicit_year else int(ctx.get('year', today.year)), month=named_month)
        if not s or re.search(r'\b(salary|payday|sometime|sometime|later|soon|couple|weeks)\b|\bend of\b|\bmonth end\b', s) or s in months:
            return None, ctx, 'vague'
        s = re.sub(r'^(on\s+|the\s+|at\s+)+', '', s).strip()
        match = re.fullmatch(r'(\d{1,2})[/.\-](\d{1,2})(?:[/.\-](\d{4}))?', s)
        if match:
            return datetime.date(int(match.group(3) or ctx.get('year', today.year)), int(match.group(2)), int(match.group(1))), ctx, 'exact'
        weekday = next((index for index, name in enumerate(weekdays) if re.search(r'\b' + name + r'\b', s)), -1)
        explicit_week = ''
        if weekday >= 0:
            if re.search(r'\bnext\s+' + weekdays[weekday] + r'\b', s):
                explicit_week = 'next'
            elif re.search(r'\bthis\s+' + weekdays[weekday] + r'\b', s):
                explicit_week = 'this'
            if explicit_week:
